const config=window.RYU_CONFIG;
const booking=document.querySelector('#booking-dialog');
document.querySelectorAll('.book').forEach(b=>b.addEventListener('click',()=>{if(config.bookingUrl){location.href=config.bookingUrl;return;}booking.showModal();}));
if(config.bookingEmail){document.querySelector('#booking-note').textContent='Tell me what you have in mind. Let’s bring it to life.';document.querySelector('#inquiry-action').textContent='Send inquiry';}
document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').addEventListener('click',()=>d.close());d.addEventListener('close',()=>d.querySelectorAll('video').forEach(v=>v.pause()));});
document.querySelector('#success-ok').addEventListener('click',()=>document.querySelector('#success-dialog').close());
document.querySelector('#inquiry').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.target);const brief=`RYU Films — Project Inquiry\n\nName: ${data.get('name')}\nEmail: ${data.get('email')}\nProject: ${data.get('type')}\n\n${data.get('details')}`;
if(config.bookingEmail){const status=document.querySelector('.form-status'),btn=document.querySelector('#inquiry-action');btn.disabled=true;status.textContent='Sending…';fetch('/api/inquiry',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(data))}).then(r=>{if(!r.ok)throw new Error(r.status);status.textContent='';e.target.reset();booking.close();document.querySelector('#success-dialog').showModal();}).catch(()=>{status.textContent='Sorry, your inquiry could not be sent. Please try again in a moment.';}).finally(()=>{btn.disabled=false;});}else{const url=URL.createObjectURL(new Blob([brief],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='RYU-Films-Project-Brief.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('.form-status').textContent='Project brief downloaded. Nothing has been sent; share this file directly with RYU.';}});
